/*
 * HAS THIS ACCOUNT ACCEPTED THE CURRENT PRIVACY NOTICE? (TASK-L185 §2)
 *
 * The ONE place the server knows the notice's version. `acceptPrivacy` writes
 * it, and `capture` and `finishStep` refuse while it is stale — all three read
 * it from here rather than spelling it three times. The browser's copy is the
 * `privacy.version` string in Data/Strings; tools/build-privacy.mjs writes BOTH
 * from privacy/notice.en.json and tools/check-privacy.mjs fails if they differ.
 *
 * EQUALITY, never "at least": a version is an opaque key, and a changed notice
 * must ask everybody again (the product's L53). Nothing is back-filled: an
 * account that has never accepted has no `privacyVersion` and is not current.
 *
 * IDENTITY COMES FROM THE SESSION: `userId` is the Request node's, never an
 * argument a caller sets.
 */
/* NOTICE_VERSION:begin — GENERATED by tools/build-privacy.mjs, do not hand-edit */
const NOTICE_VERSION = '2026-10-03';
/* NOTICE_VERSION:end */
if (Inputs.userId !== undefined) {
  (async () => {
    try {
      const userId = String(Inputs.userId || '');
      Outputs.version = NOTICE_VERSION;
      if (!userId) {
        Outputs.current = false;
        Outputs.done();
        return;
      }
      const users = await Noodl.Records.query('_User', { objectId: { equalTo: userId } }, { limit: 2, plain: true });
      if (users.length !== 1) throw new Error(users.length ? 'two accounts for one id' : 'no account');
      Outputs.current = users[0].privacyVersion === NOTICE_VERSION;
      Outputs.done();
    } catch (e) {
      Outputs.error = String((e && e.message) || e);
      console.error('[dbt:Notice] ' + Outputs.error);
      Outputs.failed();
    }
  })();
}
